namespace GeetaStudio.Api;

internal static class SourceAdminPage
{
    public const string Html = """
<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Source registry · Geeta Studio</title>
<style>body{font:17px system-ui;max-width:950px;margin:40px auto;padding:0 20px;color:#20312a;background:#faf9f5}fieldset{margin:24px 0;padding:20px;border:1px solid #b5c1b9;border-radius:8px}label{display:block;margin:12px 0}input,select,button{font:inherit;padding:8px;max-width:90%}input:not([type=checkbox]){width:90%}button{background:#254f3c;color:white;border:0;border-radius:4px;cursor:pointer;margin:5px}pre{white-space:pre-wrap;overflow-wrap:anywhere}small{display:block}#notice{white-space:pre-wrap}section{padding:12px;border-bottom:1px solid #b5c1b9}</style>
<h1>Source registry</h1><p>Register sources and editions, import approved text files, and review evidence. New work stays restricted until its permission and snapshot have been reviewed. A web address does not establish permission.</p>
<label>Tenant <select id="tenant"></select></label><label>Universe <select id="universe"></select></label><button id="reload">Refresh records</button><p id="notice" role="status"></p>
<fieldset><legend>Register a work</legend><form id="workForm"><label>Reference key <input name="key" required maxlength="200"></label><label>Title <input name="title" required maxlength="200"></label><label>Kind <select name="kind"><option>Synthetic</option><option>Fiction</option><option>Canonical</option><option>Translation</option><option>Interpretation</option><option>CurrentEvent</option><option>Historical</option></select></label><button>Register work</button></form></fieldset>
<label>Selected work <select id="work"></select></label>
<fieldset><legend>Add an edition</legend><form id="editionForm"><label>Edition key <input name="key" required></label><label>Author <input name="author" required></label><label>Translator (if applicable) <input name="translator"></label><label>Publisher <input name="publisher" required></label><label>Language <input name="language" value="en-IN" required></label><label>Locator (page, section or reference) <input name="locator" required maxlength="1000"></label><button>Add edition</button></form></fieldset>
<label>Selected edition <select id="edition"></select></label>
<fieldset><legend>Record a permission for review</legend><form id="permissionForm"><label>Evidence reference <input name="evidenceReference" placeholder="manual:permission-record-reference" required></label><small>Use a manual: or evidence: reference backed by an actual permission record. Review does not verify a legal claim automatically.</small><label>Allowed languages (comma separated) <input name="languages" value="en-IN" required></label><label>Allowed territories <input name="territories" value="IN" required></label><label>Allowed formats <input name="formats" value="Text,Json" required></label><label>Required attribution <input name="requiredAttribution" required maxlength="1000"></label><label>Expiry (optional) <input name="expiresUtc" type="datetime-local"></label><label><input type="checkbox" name="commercial"> Commercial use</label><label><input type="checkbox" name="adaptation"> Adaptation</label><label><input type="checkbox" name="translation"> Translation</label><label><input type="checkbox" name="aiProcessing"> AI processing</label><label><input type="checkbox" name="snapshotRetention"> Full snapshot retention</label><button>Submit permission for review</button></form></fieldset>
<fieldset><legend>Import a text file</legend><form id="fileForm"><label>UTF-8 text file (maximum 64 KiB) <input name="file" type="file" accept=".txt" required></label><label>Evidence reference <input name="evidenceReference" required placeholder="manual:file-reference"></label><label><input name="retain" type="checkbox"> Retain full snapshot (requires approved retention permission)</label><button>Import file</button></form></fieldset>
<h2>Review queue</h2><p>Only tenant administrators can approve or reject. Confirm the evidence and permission independently before approving.</p><div id="queue"></div>
<h2>Selected work</h2><pre id="detail"></pre><fieldset><legend>Revoke this work</legend><form id="revokeForm"><label>Reason / takedown request reference <input name="reason" required maxlength="1000"></label><button>Revoke and identify impacted content</button></form></fieldset>
<h2>Remediation</h2><div id="remediation"></div>
<script>
const $=id=>document.getElementById(id); let detail;
const base=()=>'/api/v1/sources/tenants/'+$('tenant').value+'/universes/'+$('universe').value;
async function call(path,data){const response=await fetch(path,{credentials:'same-origin',headers:{'Content-Type':'application/json','X-ContentOS-Staff':'1'},...(data===undefined?{}:{method:'POST',body:JSON.stringify(data)})}); const text=await response.text(); if(!response.ok) throw new Error(text); return text?JSON.parse(text):null;}
function options(id,rows,label){const previous=$(id).value;$(id).replaceChildren();for(const r of rows){const option=document.createElement('option');option.value=r.id;option.textContent=label(r);$(id).append(option);}if(rows.some(r=>r.id===previous))$(id).value=previous;}
async function run(action){try{$('notice').textContent='Working…';await action();$('notice').textContent='Saved. Records refreshed.';}catch(e){$('notice').textContent=e.message;}}
async function refresh(){if(!$('universe').value)return;const rows=await call(base()+'/');options('work',rows,r=>r.title+' ('+r.kind+(r.revoked?', revoked':'')+')');await inspect();const queue=await call(base()+'/review-queue');$('queue').replaceChildren();for(const [kind,items] of [['snapshots',queue.snapshots],['permissions',queue.permissions]])for(const item of items){const section=document.createElement('section');const text=document.createElement('pre');text.textContent=JSON.stringify(item,null,2);section.append(text);for(const status of ['Approved','Rejected']){const button=document.createElement('button');button.textContent=status==='Approved'?'Approve':'Reject';button.onclick=()=>run(async()=>{await call(base()+'/'+kind+'/'+item.id+'/review',{expectedRowVersion:item.rowVersion,status});await refresh();});section.append(button);}$('queue').append(section);}
$('remediation').replaceChildren();for(const item of await call(base()+'/remediation')){const section=document.createElement('section');const text=document.createElement('pre');text.textContent=JSON.stringify(item,null,2);section.append(text);if(item.status==='Open'){const input=document.createElement('input');input.placeholder='manual:resolution-evidence';section.append(input);const button=document.createElement('button');button.textContent='Mark resolved';button.onclick=()=>run(async()=>{await call(base()+'/remediation/'+item.id+'/resolve',{expectedRowVersion:item.rowVersion,evidenceReference:input.value});await refresh();});section.append(button);}$('remediation').append(section);}}
async function inspect(){if(!$('work').value){detail=null;$('detail').textContent='No registered works.';options('edition',[],r=>r.key);return;}detail=await call(base()+'/works/'+$('work').value);$('detail').textContent=JSON.stringify(detail,null,2);options('edition',detail.editions,r=>r.key+' · version '+r.version);}
async function universes(){const rows=await call('/api/v1/core/tenants/'+$('tenant').value+'/universes');options('universe',rows.filter(r=>r.tenantId===$('tenant').value),r=>r.name);await refresh();}
function form(id,action){$(id).onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);run(async()=>{await action(f);await refresh();});};}
form('workForm',f=>call(base()+'/works',{operationId:crypto.randomUUID(),key:f.get('key'),title:f.get('title'),kind:f.get('kind')}));
form('editionForm',f=>call(base()+'/works/'+$('work').value+'/editions',{operationId:crypto.randomUUID(),key:f.get('key'),author:f.get('author'),translator:f.get('translator')||null,publisher:f.get('publisher'),language:f.get('language'),locator:f.get('locator')}));
form('permissionForm',f=>call(base()+'/editions/'+$('edition').value+'/permissions',{operationId:crypto.randomUUID(),evidenceReference:f.get('evidenceReference'),languages:f.get('languages').split(',').map(x=>x.trim()),territories:f.get('territories').split(',').map(x=>x.trim()),formats:f.get('formats').split(',').map(x=>x.trim()),requiredAttribution:f.get('requiredAttribution'),commercial:f.has('commercial'),adaptation:f.has('adaptation'),translation:f.has('translation'),aiProcessing:f.has('aiProcessing'),snapshotRetention:f.has('snapshotRetention'),expiresUtc:f.get('expiresUtc')?new Date(f.get('expiresUtc')).toISOString():null}));
form('fileForm',async f=>{const file=f.get('file');if(file.size>65536)throw new Error('File exceeds 64 KiB.');const bytes=new Uint8Array(await file.arrayBuffer());const digest=new Uint8Array(await crypto.subtle.digest('SHA-256',bytes));const checksum=Array.from(digest,x=>x.toString(16).padStart(2,'0')).join('');let binary='';for(const b of bytes)binary+=String.fromCharCode(b);return call(base()+'/editions/'+$('edition').value+'/files',{operationId:crypto.randomUUID(),fileName:file.name,content:btoa(binary),expectedSha256:checksum,evidenceReference:f.get('evidenceReference'),retainFullSnapshot:f.has('retain'),retrievedUtc:new Date().toISOString()});});
form('revokeForm',f=>call(base()+'/works/'+$('work').value+'/revoke',{operationId:crypto.randomUUID(),editionId:null,reason:f.get('reason'),expectedRowVersion:detail.work.rowVersion}));
$('reload').onclick=()=>run(refresh);$('tenant').onchange=()=>run(universes);$('universe').onchange=()=>run(refresh);$('work').onchange=()=>run(inspect);
run(async()=>{options('tenant',await call('/api/v1/core/tenants'),r=>r.name);await universes();$('notice').textContent='Select your tenant and universe to begin.';});
</script></html>
""";
}
